import{_ as e,o as d,c as a,a0 as r}from"./chunks/framework.CLbANrvH.js";const b=JSON.parse('{"title":"Supported Models & Backends","description":"","frontmatter":{"title":"Supported Models & Backends"},"headers":[],"relativePath":"reference/models.md","filePath":"reference/models.md","lastUpdated":1791849617000}'),o={name:"reference/models.md"};function n(i,t,c,l,s,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="supported-models-backends" tabindex="-1">Supported Models &amp; Backends <a class="header-anchor" href="#supported-models-backends" aria-label="Permalink to &quot;Supported Models &amp; Backends&quot;">​</a></h1><p>This page is generated from the authoritative catalog in <a href="https://github.com/iBLOC/neuron/blob/main/src/capabilities/catalog.rs" target="_blank" rel="noreferrer"><code>src/capabilities/catalog.rs</code></a> (<code>default_capabilities()</code>). Every entry is what <code>/v1/models</code> advertises with <code>is_default</code> / engine metadata. For measured speed and memory numbers see <a href="/neuron/reference/benchmarks">/reference/benchmarks</a>.</p><h2 id="platform-default" tabindex="-1">Platform default <a class="header-anchor" href="#platform-default" aria-label="Permalink to &quot;Platform default&quot;">​</a></h2><p><strong><code>minicpm5-1b</code></strong> (OpenBMB, Apache-2.0) — 1B <code>LlamaForCausalLM</code>, 131K context, hybrid <code>&lt;think&gt;</code> reasoning, runs on candle (CPU f16 or CUDA bf16). Registered under the <code>candle</code> engine; tag <code>is_default: true</code>.</p><h2 id="capability-×-model-×-engine-matrix" tabindex="-1">Capability × model × engine matrix <a class="header-anchor" href="#capability-×-model-×-engine-matrix" aria-label="Permalink to &quot;Capability × model × engine matrix&quot;">​</a></h2><p>Engines are the <code>engine_impl</code> strings used in config registrations and <code>/v1/models</code>; per-request inference <em>executors</em> (e.g. tract vs ort inside the OCR engine) are noted separately. All entries require their feature flag (see <a href="/neuron/concepts/feature-flags">/concepts/feature-flags</a>).</p><h3 id="llm-chat-streaming-tools" tabindex="-1">LLM (chat, streaming, tools) <a class="header-anchor" href="#llm-chat-streaming-tools" aria-label="Permalink to &quot;LLM (chat, streaming, tools)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>params</th><th>notes</th></tr></thead><tbody><tr><td>qwen2.5-0.5b</td><td>candle</td><td>0.5B</td><td>edge tier</td></tr><tr><td>qwen3-0.6b</td><td>candle</td><td>0.6B</td><td></td></tr><tr><td><strong>minicpm5-1b</strong></td><td>candle</td><td>1B</td><td>platform default, 131K ctx</td></tr><tr><td>minicpm5-2b</td><td>candle</td><td>2.52B</td><td>~6-7 GB VRAM (bf16)</td></tr><tr><td>llama-3-8b</td><td>candle</td><td>8B</td><td></td></tr><tr><td>phi-3-mini</td><td>candle</td><td>3.8B</td><td></td></tr><tr><td>mistral-7b</td><td>candle</td><td>7B</td><td></td></tr><tr><td>chatglm-3-6b</td><td>candle</td><td>6B</td><td></td></tr><tr><td>gemma-3n-e2b-it / e4b-it</td><td>litert</td><td>2B / 4B eff.</td><td>on-device (LiteRT-LM)</td></tr><tr><td>gemma-3-12b-it / gemma-4-e2b-it / gemma-4-e4b-it / gemma-4-12b-it</td><td>litert</td><td>—</td><td>on-device</td></tr><tr><td>minicpm5-1b</td><td>litert</td><td>1B</td><td>same weights, LiteRT path</td></tr><tr><td>Qwen/Qwen3-0.6B</td><td>mistralrs</td><td>0.6B</td><td>ISQ quantized (q4_0 default)</td></tr><tr><td>microsoft/Mage-VL</td><td>mage_vl</td><td>4B</td><td>image+video, own candle port</td></tr></tbody></table><h3 id="tts-speech-synthesis" tabindex="-1">TTS (speech synthesis) <a class="header-anchor" href="#tts-speech-synthesis" aria-label="Permalink to &quot;TTS (speech synthesis)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>voxcpm-0.5b</td><td>burn</td><td>pre-converted burn weights, edge tier</td></tr><tr><td>voxcpm2</td><td>burn</td><td>2.29B, 48 kHz, 30 languages, voice cloning; ~10 GB RAM (f32)</td></tr></tbody></table><h3 id="asr-transcription" tabindex="-1">ASR (transcription) <a class="header-anchor" href="#asr-transcription" aria-label="Permalink to &quot;ASR (transcription)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>sensevoice-small</td><td>sherpa</td><td>official sherpa-onnx binding</td></tr><tr><td>sensevoice-small</td><td>tract</td><td>pure-Rust ONNX path; needs the prep script</td></tr><tr><td>whisper-base</td><td>candle</td><td></td></tr></tbody></table><h3 id="rerank" tabindex="-1">Rerank <a class="header-anchor" href="#rerank" aria-label="Permalink to &quot;Rerank&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>bge-reranker-base</td><td>candle</td><td>~1.08 GB</td></tr><tr><td>mxbai-rerank-base-v2</td><td>candle</td><td></td></tr><tr><td>jina-reranker-base-v2</td><td>candle</td><td></td></tr><tr><td>rerank-english-v3.0 / rerank-multilingual-v3.0</td><td>cohere (hosted API)</td><td>no local weights; <code>NEURON_COHERE_API_KEY</code></td></tr></tbody></table><h3 id="embedding" tabindex="-1">Embedding <a class="header-anchor" href="#embedding" aria-label="Permalink to &quot;Embedding&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>all-minilm-l6-v2</td><td>candle</td><td>~88 MB, batched forward, base64 output</td></tr></tbody></table><h3 id="vision-detection-grounding" tabindex="-1">Vision (detection / grounding) <a class="header-anchor" href="#vision-detection-grounding" aria-label="Permalink to &quot;Vision (detection / grounding)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>yolov8n / yolov8s / yolov11n</td><td>candle</td><td>clean-room YOLOv8 arch; n ≈ 6 MB</td></tr><tr><td>rtdetr-r50 / detr-resnet50</td><td>candle</td><td>transformer detectors, no NMS</td></tr><tr><td>rf-detr-base / rf-detr-large</td><td>ort</td><td>ONNX executor</td></tr><tr><td>florence-2-base</td><td>ort</td><td>prompt-driven VLM</td></tr></tbody></table><h3 id="ocr-detection-recognition-optional-layout-tables" tabindex="-1">OCR (detection + recognition, optional layout + tables) <a class="header-anchor" href="#ocr-detection-recognition-optional-layout-tables" aria-label="Permalink to &quot;OCR (detection + recognition, optional layout + tables)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>ppocrv5-mobile</td><td>paddle-ocr</td><td>det+rec ~21 MB</td></tr><tr><td>ppocrv5-server</td><td>paddle-ocr</td><td>det 88 MB + rec 85 MB</td></tr><tr><td>ppocrv6-medium</td><td>paddle-ocr</td><td>det 62 MB + rec 77 MB, 50 languages</td></tr></tbody></table><p>The engine&#39;s session executor is pluggable: <code>tract</code> (pure Rust, default) or <code>ort</code> (onnxruntime, ~10× faster). Optional add-on models in the same directory: <code>rec-&lt;pack&gt;/</code> language packs (109 scripts), <code>layout.onnx</code> (PP-DocLayoutV3, ~130 MB), <code>table.onnx</code> (SLANeXt, ~368 MB). See <a href="/neuron/howto/ocr">/howto/ocr</a>.</p><h3 id="decision-scoring-—-runtime-capable-not-in-the-default-catalog" tabindex="-1">Decision scoring — runtime-capable, not in the default catalog <a class="header-anchor" href="#decision-scoring-—-runtime-capable-not-in-the-default-catalog" aria-label="Permalink to &quot;Decision scoring — runtime-capable, not in the default catalog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>laya (+ multilingual, typed-decisions)</td><td>tract</td><td>int8 encoder-only ONNX, ~500 MB; register via <code>NEURON_DECISION_MODEL_PATH</code>; needs the prep script</td></tr></tbody></table><h3 id="time-series-forecasting-—-runtime-capable-not-in-the-default-catalog" tabindex="-1">Time-series forecasting — runtime-capable, not in the default catalog <a class="header-anchor" href="#time-series-forecasting-—-runtime-capable-not-in-the-default-catalog" aria-label="Permalink to &quot;Time-series forecasting — runtime-capable, not in the default catalog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>model</th><th>engine</th><th>notes</th></tr></thead><tbody><tr><td>chronos2</td><td>candle (chronos2 feature)</td><td>vendored T5-style encoder/decoder; register via <code>NEURON_CHRONOS2_MODEL_PATH</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Catalog vs runtimes</p><p>Decision and Chronos2 have full runtime implementations and HTTP endpoints but ship no default catalog entry, because nothing downloadable loads as-is (Laya needs its export/prep pipeline; Chronos2 needs a checkpoint). Register them explicitly via env vars — see <a href="/neuron/reference/env-vars">/reference/env-vars</a>.</p></div><h2 id="engine-naming" tabindex="-1">Engine naming <a class="header-anchor" href="#engine-naming" aria-label="Permalink to &quot;Engine naming&quot;">​</a></h2><p><code>engine_impl</code> (what registrations use) differs from the runtime-selection env vars:</p><table tabindex="0"><thead><tr><th>engine_impl</th><th>selected by</th></tr></thead><tbody><tr><td>candle</td><td><code>NEURON_LLM_RUNTIME=candle</code> / vision <code>candle-yolo</code> / rerank runtimes</td></tr><tr><td>tract</td><td><code>NEURON_ASR_RUNTIME=tract</code>, <code>NEURON_DECISION_RUNTIME=tract</code>, OCR executor</td></tr><tr><td>ort</td><td>vision <code>NEURON_VISION_RUNTIME=ort</code>, OCR executor <code>NEURON_OCR_EXECUTOR=ort</code></td></tr><tr><td>sherpa</td><td><code>NEURON_ASR_RUNTIME=sherpa</code></td></tr><tr><td>burn</td><td><code>NEURON_TTS_RUNTIME=voxcpm</code> / <code>voxcpm2</code></td></tr><tr><td>litert</td><td><code>NEURON_LLM_RUNTIME=litert</code></td></tr><tr><td>mistralrs</td><td><code>NEURON_LLM_RUNTIME=mistralrs</code></td></tr><tr><td>mage_vl</td><td><code>NEURON_LLM_RUNTIME=mage_vl</code></td></tr><tr><td>cohere</td><td><code>NEURON_RERANK_RUNTIME=cohere</code> (hosted)</td></tr><tr><td>paddle-ocr</td><td>config registration <code>capability = &quot;ocr&quot;, engine = &quot;paddle-ocr&quot;</code></td></tr></tbody></table>',29)])])}const p=e(o,[["render",n]]);export{b as __pageData,p as default};
